151	  const legacyKey = (e: {
152	    dateStr: string;
153	    subject: string;
154	    direction: string;
155	    threadId?: string;
156	  }) => `${e.dateStr}|${e.subject}|${e.direction}|${e.threadId ?? ""}`;
