// Slice 4 — pure merge/splice of new entries into a contact file.
//
// mergeContact() is the whole writer's brain: it owns the "## Mark's Email
// History" section and nothing else. Everything from "## Email History" onward
// (Heather's mbox data) is preserved byte-for-byte.

export interface FetchedEntry {
  ts: number; // internalDate ms
  dateStr: string; // YYYY-MM-DD
  subject: string;
  direction: string;
  threadId: string;
  messageId: string;
  link: string;
  summary?: string;
}

// Parsed form of an entry already in the file — legacy Cowork entries may lack
// message id / link, so those are optional.
interface Entry {
  ts: number;
  dateStr: string;
  subject: string;
  direction: string;
  summary?: string;
  threadId?: string;
  messageId?: string;
  link?: string;
}

export interface MergeResult {
  content: string;
  added: number;
  status: "written" | "skipped-malformed";
}

const MARK_HEADING_RE = /^##[ \t]+Mark's Email History[ \t]*$/m;
const NEXT_H2_RE = /^##[ \t]+/m;

function parseEntries(markBody: string): Entry[] {
  const entries: Entry[] = [];
  let curDate = "";
  let cur: Entry | null = null;

  const push = () => {
    if (cur) entries.push(cur);
    cur = null;
  };

  for (const line of markBody.split(/\r?\n/)) {
    const date = line.match(/^###\s+(\d{4}-\d{2}-\d{2})/);
    if (date) {
      push();
      curDate = date[1];
      continue;
    }
    const subj = line.match(/^-\s+\*\*Subject:\*\*\s*(.+?)\s*$/);
    if (subj) {
      push();
      cur = {
        ts: Date.parse(`${curDate}T00:00:00Z`),
        dateStr: curDate,
        subject: subj[1],
        direction: "",
      };
      continue;
    }
    if (!cur) continue;
    const dir = line.match(/^\s*-\s*Direction:\s*(.+?)\s*$/);
    if (dir) cur.direction = dir[1];
    const sum = line.match(/^\s*-\s*Summary:\s*(.+?)\s*$/);
    if (sum) cur.summary = sum[1];
    const thr = line.match(/^\s*-\s*Thread:\s*(.+?)\s*$/);
    if (thr) cur.threadId = thr[1];
    const msg = line.match(/^\s*-\s*Message:\s*(.+?)\s*$/);
    if (msg) cur.messageId = msg[1];
    const lnk = line.match(/^\s*-\s*Link:\s*(.+?)\s*$/);
    if (lnk) cur.link = lnk[1];
  }
  push();
  return entries;
}

function renderEntry(e: Entry): string[] {
  const lines = [`- **Subject:** ${e.subject}`, `  - Direction: ${e.direction}`];
  if (e.summary) lines.push(`  - Summary: ${e.summary}`);
  if (e.threadId) lines.push(`  - Thread: ${e.threadId}`);
  if (e.messageId) lines.push(`  - Message: ${e.messageId}`);
  if (e.link) lines.push(`  - Link: ${e.link}`);
  return lines;
}

function renderSection(entries: Entry[]): string {
  const sorted = [...entries].sort((a, b) => b.ts - a.ts);
  const lines: string[] = [];
  let curDate = "";
  for (const e of sorted) {
    if (e.dateStr !== curDate) {
      curDate = e.dateStr;
      lines.push(`### ${curDate}`);
    }
    lines.push(...renderEntry(e));
    lines.push("");
  }
  return lines.join("\n");
}

// Update-or-insert frontmatter fields inside the leading `---` block of `head`,
// leaving every other line (name, email/emails list) untouched.
function updateFrontmatter(head: string, fields: Record<string, string>): string {
  const fm = head.match(/^---\r?\n([\s\S]*?)(\r?\n)---/);
  if (!fm) return head;
  let inner = fm[1];
  for (const [key, value] of Object.entries(fields)) {
    const re = new RegExp(`^${key}:.*$`, "m");
    if (re.test(inner)) inner = inner.replace(re, `${key}: ${value}`);
    else inner = `${inner}\n${key}: ${value}`;
  }
  return head.slice(0, fm.index! ) + `---\n${inner}\n---` + head.slice(fm.index! + fm[0].length);
}

export function mergeContact(
  existingContent: string,
  fetched: FetchedEntry[],
  today: string
): MergeResult {
  const headingMatch = existingContent.match(MARK_HEADING_RE);
  if (!headingMatch || headingMatch.index === undefined) {
    return { content: existingContent, added: 0, status: "skipped-malformed" };
  }

  const headingStart = headingMatch.index;
  const afterHeading = headingStart + headingMatch[0].length;

  // The mbox section (if any) starts at the next H2 after the Mark heading.
  const rest = existingContent.slice(afterHeading);
  const nextH2 = rest.match(NEXT_H2_RE);
  const markBody =
    nextH2 && nextH2.index !== undefined ? rest.slice(0, nextH2.index) : rest;
  const tail =
    nextH2 && nextH2.index !== undefined ? rest.slice(nextH2.index) : "";

  const rawHead = existingContent.slice(0, headingStart);

  const existing = parseEntries(markBody);
  const existingIds = new Set(
    existing.map((e) => e.messageId).filter((id): id is string => !!id)
  );
  // Legacy entries (no Message id) dedup on an exact 4-tuple. Exact only — a
  // looser match risks silently dropping a real message.
  const legacyKey = (e: {
    dateStr: string;
    subject: string;
    direction: string;
    threadId?: string;
  }) => `${e.dateStr}|${e.subject}|${e.direction}|${e.threadId ?? ""}`;
  const legacyKeys = new Set(
    existing.filter((e) => !e.messageId).map(legacyKey)
  );
  const fresh = fetched.filter(
    (f) => !existingIds.has(f.messageId) && !legacyKeys.has(legacyKey(f))
  );
  const merged: Entry[] = [...existing, ...fresh];
  const added = fresh.length;

  // last_searched always advances; last_updated only when we actually changed entries.
  const fields: Record<string, string> = { last_searched: today };
  if (added > 0) fields.last_updated = today;
  const head = updateFrontmatter(rawHead, fields);

  // Nothing new: keep the section (entries or placeholder) byte-for-byte and only
  // bump last_searched. Otherwise regenerate the section from the merged entries.
  const heading = headingMatch[0];
  const body = added > 0 ? `\n\n${renderSection(merged)}\n` : markBody;
  let content = `${head}${heading}${body}${tail}`;
  // When Mark's section is the last thing in the file (friends/colleagues have no
  // "## Email History"), collapse the trailing blank line to a single newline.
  if (tail === "") content = content.replace(/\n+$/, "\n");

  return { content, added, status: "written" };
}

