1	import * as fs from "node:fs";
2	import * as readline from "node:readline";
3	import * as path from "node:path";
4	
5	const MBOX_DIR = path.resolve(__dirname, "..", "mbox");
6	const CSV_PATH = path.resolve(__dirname, "..", "correspondents-filtered.csv");
7	const CLIENT_DIR = path.resolve(__dirname, "..", "client");
8	
9	const OWNER_ADDRESSES = new Set([
10	  "heather.uhl@agilepainrelief.com",
11	  "heather.uhl@felicisholdings.com",
12	  "heather.uhl@smart-life-choices.com",
13	  "heatheruhl@gmail.com",
14	]);
15	
16	// ─── CSV parsing ────────────────────────────────────────────────────────────
17	
18	function parseCSVLine(line: string): string[] {
19	  const fields: string[] = [];
20	  let current = "";
21	  let inQuotes = false;
22	
23	  for (let i = 0; i < line.length; i++) {
24	    const ch = line[i];
25	    if (inQuotes) {
26	      if (ch === '"') {
27	        if (i + 1 < line.length && line[i + 1] === '"') {
28	          current += '"';
29	          i++;
30	        } else {
31	          inQuotes = false;
32	        }
33	      } else {
34	        current += ch;
35	      }
36	    } else {
37	      if (ch === '"') {
38	        inQuotes = true;
39	      } else if (ch === ",") {
40	        fields.push(current);
41	        current = "";
42	      } else {
43	        current += ch;
44	      }
45	    }
46	  }
47	  fields.push(current);
48	  return fields;
49	}
50	
51	// ─── Address parsing ────────────────────────────────────────────────────────
52	
53	function splitAddresses(field: string): string[] {
54	  const parts: string[] = [];
55	  let current = "";
56	  let inAngle = 0;
57	  let inQuote = false;
58	
59	  for (const ch of field) {
60	    if (ch === '"' && inAngle === 0) {
61	      inQuote = !inQuote;
62	      current += ch;
63	    } else if (ch === "<" && !inQuote) {
64	      inAngle++;
65	      current += ch;
66	    } else if (ch === ">" && !inQuote) {
67	      inAngle = Math.max(0, inAngle - 1);
68	      current += ch;
69	    } else if (ch === "," && inAngle === 0 && !inQuote) {
70	      parts.push(current);
71	      current = "";
72	    } else {
73	      current += ch;
74	    }
75	  }
76	  if (current.trim()) parts.push(current);
77	  return parts;
78	}
79	
80	function parseAddresses(
81	  field: string
82	): Array<{ name: string; email: string }> {
83	  const results: Array<{ name: string; email: string }> = [];
84	  const parts = splitAddresses(field);
85	
86	  for (const part of parts) {
87	    const trimmed = part.trim();
88	    if (!trimmed) continue;
89	
90	    const angleMatch = trimmed.match(/^(.*?)\s*<([^>]+)>/);
91	    if (angleMatch) {
92	      const name = angleMatch[1].replace(/^["']|["']$/g, "").trim();
93	      const email = angleMatch[2].trim().toLowerCase();
94	      if (email.includes("@")) {
95	        results.push({ name, email });
96	      }
97	      continue;
98	    }
99	
100	    const bareMatch = trimmed.match(/[\w.+\-]+@[\w.\-]+\.\w+/);
101	    if (bareMatch) {
102	      const email = bareMatch[0].toLowerCase();
103	      results.push({ name: "", email });
104	    }
105	  }
106	  return results;
107	}
108	
109	function isOwner(email: string): boolean {
110	  return OWNER_ADDRESSES.has(email);
111	}
112	
113	function parseDate(dateStr: string): Date | null {
114	  const d = new Date(dateStr.trim());
115	  return isNaN(d.getTime()) ? null : d;
116	}
117	
118	// ─── Name parsing ───────────────────────────────────────────────────────────
119	
120	interface ClientName {
121	  firstName: string;
122	  lastName: string;
123	}
124	
125	function parseName(raw: string): ClientName {
126	  const trimmed = raw.trim();
127	  if (!trimmed) return { firstName: "", lastName: "" };
128	
129	  // Handle "Last, First" or "Last, First (org)" format
130	  if (trimmed.includes(",")) {
131	    const parts = trimmed.split(",");
132	    const lastName = parts[0].trim();
133	    // Take just the name part, strip any parenthetical suffix
134	    const firstName = parts
135	      .slice(1)
136	      .join(",")
137	      .trim()
138	      .replace(/\s*\(.*\)\s*$/, "")
139	      .replace(/\s*\[.*\]\s*$/, "")
140	      .trim();
141	    return { firstName, lastName };
142	  }
143	
144	  // Handle "First Last" format — strip parenthetical/bracket suffixes
145	  const cleaned = trimmed
146	    .replace(/\s*\(.*\)\s*$/, "")
147	    .replace(/\s*\[.*\]\s*$/, "")
148	    .trim();
149	  const parts = cleaned.split(/\s+/);
150	  if (parts.length === 1) {
151	    return { firstName: parts[0], lastName: "" };
152	  }
153	  const lastName = parts[parts.length - 1];
154	  const firstName = parts.slice(0, -1).join(" ");
155	  return { firstName, lastName };
156	}
157	
158	// ─── Slug / filename generation ─────────────────────────────────────────────
159	
160	function slugify(s: string): string {
161	  return s
162	    .toLowerCase()
163	    .normalize("NFD")
164	    .replace(/[\u0300-\u036f]/g, "") // strip accents
165	    .replace(/[^a-z0-9]+/g, "-")
166	    .replace(/^-+|-+$/g, "");
167	}
168	
169	function makeFilename(
170	  client: ClientName,
171	  email: string,
172	  usedFilenames: Set<string>
173	): string {
174	  let base: string;
175	  if (client.lastName && client.firstName) {
176	    base = slugify(`${client.lastName}-${client.firstName}`);
177	  } else if (client.lastName) {
178	    base = slugify(client.lastName);
179	  } else if (client.firstName) {
180	    base = slugify(client.firstName);
181	  } else {
182	    // Use email local part
183	    const local = email.split("@")[0];
184	    base = slugify(local);
185	  }
186	
187	  if (!base) base = slugify(email.replace("@", "-at-"));
188	
189	  let filename = base;
190	  if (usedFilenames.has(filename)) {
191	    const domain = email.split("@")[1]?.split(".")[0] || "dup";
192	    filename = `${base}-${slugify(domain)}`;
193	  }
194	  // Final dedup with counter
195	  let final = filename;
196	  let counter = 2;
197	  while (usedFilenames.has(final)) {
198	    final = `${filename}-${counter}`;
199	    counter++;
200	  }
201	  usedFilenames.add(final);
202	  return final + ".md";
203	}
204	
205	// ─── Email record types ─────────────────────────────────────────────────────
206	
207	interface EmailRecord {
208	  date: Date;
209	  dateStr: string; // YYYY-MM-DD
210	  subject: string;
211	  direction: "From client" | "To client" | "CC'd";
212	  threadId: string;
213	  messageId: string;
214	}
215	
216	interface ClientData {
217	  csvName: string;
218	  parsedName: ClientName;
219	  email: string;
220	  emails: EmailRecord[];
221	  // Track name from headers in case CSV has none
222	  headerName: string;
223	}
224	
225	// ─── Load CSV ───────────────────────────────────────────────────────────────
226	
227	function loadClients(): Map<string, ClientData> {
228	  const raw = fs.readFileSync(CSV_PATH, "utf-8");
229	  const lines = raw.split("\n").filter((l) => l.trim() !== "");
230	  const clients = new Map<string, ClientData>();
231	
232	  // Skip header
233	  for (let i = 1; i < lines.length; i++) {
234	    const fields = parseCSVLine(lines[i]);
235	    if (fields.length < 2) continue;
236	
237	    const name = fields[0].trim();
238	    const email = fields[1].trim().toLowerCase();
239	    if (!email) continue;
240	
241	    clients.set(email, {
242	      csvName: name,
243	      parsedName: parseName(name),
244	      email,
245	      emails: [],
246	      headerName: "",
247	    });
248	  }
249	
250	  return clients;
251	}
252	
253	// ─── Decode RFC 2047 encoded words ──────────────────────────────────────────
254	
255	function decodeRFC2047(s: string): string {
256	  return s.replace(
257	    /=\?([^?]+)\?([BbQq])\?([^?]*)\?=/g,
258	    (_match, charset, encoding, encoded) => {
259	      try {
260	        if (encoding.toUpperCase() === "B") {
261	          const buf = Buffer.from(encoded, "base64");
262	          return buf.toString(charset.toLowerCase() === "utf-8" ? "utf-8" : "latin1");
263	        } else {
264	          // Q encoding
265	          const decoded = encoded
266	            .replace(/_/g, " ")
267	            .replace(/=([0-9A-Fa-f]{2})/g, (_: string, hex: string) =>
268	              String.fromCharCode(parseInt(hex, 16))
269	            );
270	          return decoded;
271	        }
272	      } catch {
273	        return encoded;
274	      }
275	    }
276	  );
277	}
278	
279	// ─── Process mbox ───────────────────────────────────────────────────────────
