import * as fs from "node:fs";
import * as readline from "node:readline";
import * as path from "node:path";

const MBOX_DIR = path.resolve(__dirname, "..", "mbox");
const CSV_PATH = path.resolve(__dirname, "..", "correspondents-filtered.csv");
const CLIENT_DIR = path.resolve(__dirname, "..", "client");

const OWNER_ADDRESSES = new Set([
  "heather.uhl@agilepainrelief.com",
  "heather.uhl@felicisholdings.com",
  "heather.uhl@smart-life-choices.com",
  "heatheruhl@gmail.com",
]);

// ─── CSV parsing ────────────────────────────────────────────────────────────

function parseCSVLine(line: string): string[] {
  const fields: string[] = [];
  let current = "";
  let inQuotes = false;

  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (inQuotes) {
      if (ch === '"') {
        if (i + 1 < line.length && line[i + 1] === '"') {
          current += '"';
          i++;
        } else {
          inQuotes = false;
        }
      } else {
        current += ch;
      }
    } else {
      if (ch === '"') {
        inQuotes = true;
      } else if (ch === ",") {
        fields.push(current);
        current = "";
      } else {
        current += ch;
      }
    }
  }
  fields.push(current);
  return fields;
}

// ─── Address parsing ────────────────────────────────────────────────────────

function splitAddresses(field: string): string[] {
  const parts: string[] = [];
  let current = "";
  let inAngle = 0;
  let inQuote = false;

  for (const ch of field) {
    if (ch === '"' && inAngle === 0) {
      inQuote = !inQuote;
      current += ch;
    } else if (ch === "<" && !inQuote) {
      inAngle++;
      current += ch;
    } else if (ch === ">" && !inQuote) {
      inAngle = Math.max(0, inAngle - 1);
      current += ch;
    } else if (ch === "," && inAngle === 0 && !inQuote) {
      parts.push(current);
      current = "";
    } else {
      current += ch;
    }
  }
  if (current.trim()) parts.push(current);
  return parts;
}

function parseAddresses(
  field: string
): Array<{ name: string; email: string }> {
  const results: Array<{ name: string; email: string }> = [];
  const parts = splitAddresses(field);

  for (const part of parts) {
    const trimmed = part.trim();
    if (!trimmed) continue;

    const angleMatch = trimmed.match(/^(.*?)\s*<([^>]+)>/);
    if (angleMatch) {
      const name = angleMatch[1].replace(/^["']|["']$/g, "").trim();
      const email = angleMatch[2].trim().toLowerCase();
      if (email.includes("@")) {
        results.push({ name, email });
      }
      continue;
    }

    const bareMatch = trimmed.match(/[\w.+\-]+@[\w.\-]+\.\w+/);
    if (bareMatch) {
      const email = bareMatch[0].toLowerCase();
      results.push({ name: "", email });
    }
  }
  return results;
}

function isOwner(email: string): boolean {
  return OWNER_ADDRESSES.has(email);
}

function parseDate(dateStr: string): Date | null {
  const d = new Date(dateStr.trim());
  return isNaN(d.getTime()) ? null : d;
}

// ─── Name parsing ───────────────────────────────────────────────────────────

interface ClientName {
  firstName: string;
  lastName: string;
}

function parseName(raw: string): ClientName {
  const trimmed = raw.trim();
  if (!trimmed) return { firstName: "", lastName: "" };

  // Handle "Last, First" or "Last, First (org)" format
  if (trimmed.includes(",")) {
    const parts = trimmed.split(",");
    const lastName = parts[0].trim();
    // Take just the name part, strip any parenthetical suffix
    const firstName = parts
      .slice(1)
      .join(",")
      .trim()
      .replace(/\s*\(.*\)\s*$/, "")
      .replace(/\s*\[.*\]\s*$/, "")
      .trim();
    return { firstName, lastName };
  }

  // Handle "First Last" format — strip parenthetical/bracket suffixes
  const cleaned = trimmed
    .replace(/\s*\(.*\)\s*$/, "")
    .replace(/\s*\[.*\]\s*$/, "")
    .trim();
  const parts = cleaned.split(/\s+/);
  if (parts.length === 1) {
    return { firstName: parts[0], lastName: "" };
  }
  const lastName = parts[parts.length - 1];
  const firstName = parts.slice(0, -1).join(" ");
  return { firstName, lastName };
}

// ─── Slug / filename generation ─────────────────────────────────────────────

function slugify(s: string): string {
  return s
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "") // strip accents
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

function makeFilename(
  client: ClientName,
  email: string,
  usedFilenames: Set<string>
): string {
  let base: string;
  if (client.lastName && client.firstName) {
    base = slugify(`${client.lastName}-${client.firstName}`);
  } else if (client.lastName) {
    base = slugify(client.lastName);
  } else if (client.firstName) {
    base = slugify(client.firstName);
  } else {
    // Use email local part
    const local = email.split("@")[0];
    base = slugify(local);
  }

  if (!base) base = slugify(email.replace("@", "-at-"));

  let filename = base;
  if (usedFilenames.has(filename)) {
    const domain = email.split("@")[1]?.split(".")[0] || "dup";
    filename = `${base}-${slugify(domain)}`;
  }
  // Final dedup with counter
  let final = filename;
  let counter = 2;
  while (usedFilenames.has(final)) {
    final = `${filename}-${counter}`;
    counter++;
  }
  usedFilenames.add(final);
  return final + ".md";
}

// ─── Email record types ─────────────────────────────────────────────────────

interface EmailRecord {
  date: Date;
  dateStr: string; // YYYY-MM-DD
  subject: string;
  direction: "From client" | "To client" | "CC'd";
  threadId: string;
  messageId: string;
}

interface ClientData {
  csvName: string;
  parsedName: ClientName;
  email: string;
  emails: EmailRecord[];
  // Track name from headers in case CSV has none
  headerName: string;
}

// ─── Load CSV ───────────────────────────────────────────────────────────────

function loadClients(): Map<string, ClientData> {
  const raw = fs.readFileSync(CSV_PATH, "utf-8");
  const lines = raw.split("\n").filter((l) => l.trim() !== "");
  const clients = new Map<string, ClientData>();

  // Skip header
  for (let i = 1; i < lines.length; i++) {
    const fields = parseCSVLine(lines[i]);
    if (fields.length < 2) continue;

    const name = fields[0].trim();
    const email = fields[1].trim().toLowerCase();
    if (!email) continue;

    clients.set(email, {
      csvName: name,
      parsedName: parseName(name),
      email,
      emails: [],
      headerName: "",
    });
  }

  return clients;
}

// ─── Decode RFC 2047 encoded words ──────────────────────────────────────────

function decodeRFC2047(s: string): string {
  return s.replace(
    /=\?([^?]+)\?([BbQq])\?([^?]*)\?=/g,
    (_match, charset, encoding, encoded) => {
      try {
        if (encoding.toUpperCase() === "B") {
          const buf = Buffer.from(encoded, "base64");
          return buf.toString(charset.toLowerCase() === "utf-8" ? "utf-8" : "latin1");
        } else {
          // Q encoding
          const decoded = encoded
            .replace(/_/g, " ")
            .replace(/=([0-9A-Fa-f]{2})/g, (_: string, hex: string) =>
              String.fromCharCode(parseInt(hex, 16))
            );
          return decoded;
        }
      } catch {
        return encoded;
      }
    }
  );
}

// ─── Process mbox ───────────────────────────────────────────────────────────

async function processMbox(
  filePath: string,
  clients: Map<string, ClientData>
): Promise<void> {
  const fileStream = fs.createReadStream(filePath, { encoding: "utf-8" });
  const rl = readline.createInterface({
    input: fileStream,
    crlfDelay: Infinity,
  });

  let inHeaders = false;
  let currentFrom = "";
  let currentTo = "";
  let currentCc = "";
  let currentSubject = "";
  let currentDate: Date | null = null;
  let currentThreadId = "";
  let currentMessageId = "";
  let lastHeaderKey = "";
  let messageCount = 0;
  let matchedCount = 0;

  function processMessage() {
    if (!currentDate) return;

    const fromAddrs = parseAddresses(currentFrom);
    const toAddrs = parseAddresses(currentTo);
    const ccAddrs = parseAddresses(currentCc);

    const subject = decodeRFC2047(currentSubject).trim() || "(no subject)";
    const dateStr = currentDate.toISOString().split("T")[0];

    // Determine if owner sent or received
    const ownerIsSender = fromAddrs.some((a) => isOwner(a.email));

    let matched = false;

    // Check From addresses
    for (const addr of fromAddrs) {
      const client = clients.get(addr.email);
      if (client) {
        client.emails.push({
          date: currentDate,
          dateStr,
          subject,
          direction: "From client",
          threadId: currentThreadId,
          messageId: currentMessageId,
        });
        if (addr.name && !client.headerName) {
          client.headerName = addr.name;
        }
        matched = true;
      }
    }

    // Check To addresses
    for (const addr of toAddrs) {
      const client = clients.get(addr.email);
      if (client) {
        // Only mark "To client" if the owner was the sender
        const direction = ownerIsSender ? "To client" : "CC'd";
        client.emails.push({
          date: currentDate,
          dateStr,
          subject,
          direction,
          threadId: currentThreadId,
          messageId: currentMessageId,
        });
        if (addr.name && !client.headerName) {
          client.headerName = addr.name;
        }
        matched = true;
      }
    }

    // Check CC addresses
    for (const addr of ccAddrs) {
      const client = clients.get(addr.email);
      if (client) {
        client.emails.push({
          date: currentDate,
          dateStr,
          subject,
          direction: "CC'd",
          threadId: currentThreadId,
          messageId: currentMessageId,
        });
        if (addr.name && !client.headerName) {
          client.headerName = addr.name;
        }
        matched = true;
      }
    }

    if (matched) matchedCount++;
  }

  for await (const line of rl) {
    if (line.startsWith("From ") && /^From \S+ .+ \d{4}$/.test(line)) {
      if (inHeaders || currentFrom || currentTo) {
        processMessage();
      }
      inHeaders = true;
      currentFrom = "";
      currentTo = "";
      currentCc = "";
      currentSubject = "";
      currentDate = null;
      currentThreadId = "";
      currentMessageId = "";
      lastHeaderKey = "";
      messageCount++;

      if (messageCount % 10000 === 0) {
        process.stderr.write(`\rProcessed ${messageCount} messages, ${matchedCount} matched...`);
      }
      continue;
    }

    if (!inHeaders) continue;

    if (line.trim() === "") {
      inHeaders = false;
      continue;
    }

    // Continuation line
    if (/^\s/.test(line)) {
      const continuation = line.trim();
      if (lastHeaderKey === "from") currentFrom += " " + continuation;
      else if (lastHeaderKey === "to") currentTo += " " + continuation;
      else if (lastHeaderKey === "cc") currentCc += " " + continuation;
      else if (lastHeaderKey === "subject") currentSubject += " " + continuation;
      continue;
    }

    const colonIdx = line.indexOf(":");
    if (colonIdx === -1) continue;

    const key = line.substring(0, colonIdx).toLowerCase();
    const value = line.substring(colonIdx + 1).trim();

    switch (key) {
      case "from":
        currentFrom = value;
        lastHeaderKey = "from";
        break;
      case "to":
        currentTo = value;
        lastHeaderKey = "to";
        break;
      case "cc":
        currentCc = value;
        lastHeaderKey = "cc";
        break;
      case "subject":
        currentSubject = value;
        lastHeaderKey = "subject";
        break;
      case "date":
        if (!currentDate) currentDate = parseDate(value);
        lastHeaderKey = "date";
        break;
      case "x-gm-thrid":
        currentThreadId = value;
        lastHeaderKey = "thrid";
        break;
      case "message-id":
        currentMessageId = value;
        lastHeaderKey = "message-id";
        break;
      default:
        lastHeaderKey = key;
        break;
    }
  }

  // Process last message
  processMessage();

  process.stderr.write(
    `\rProcessed ${messageCount} messages total, ${matchedCount} matched client emails\n`
  );
}

// ─── Generate markdown files ────────────────────────────────────────────────

function escapeYaml(s: string): string {
  if (/[:"'{}\[\]#&*!|>%@`]/.test(s) || s.trim() !== s) {
    return '"' + s.replace(/\\/g, "\\\\").replace(/"/g, '\\"') + '"';
  }
  return s;
}

function generateMarkdown(client: ClientData): string {
  // Resolve name: prefer CSV name, fall back to header name
  let name = client.parsedName;
  if (!name.firstName && !name.lastName && client.headerName) {
    name = parseName(decodeRFC2047(client.headerName));
  }

  const lines: string[] = [];

  // YAML frontmatter
  lines.push("---");
  lines.push(`last_name: ${escapeYaml(name.lastName)}`);
  lines.push(`first_name: ${escapeYaml(name.firstName)}`);
  lines.push(`email: ${escapeYaml(client.email)}`);
  lines.push("---");
  lines.push("");
  lines.push("## Email History");
  lines.push("");

  if (client.emails.length === 0) {
    lines.push("No emails found in archive.");
    lines.push("");
    return lines.join("\n");
  }

  // Sort newest to oldest
  client.emails.sort((a, b) => b.date.getTime() - a.date.getTime());

  // Group by date
  let currentDate = "";
  for (const email of client.emails) {
    if (email.dateStr !== currentDate) {
      currentDate = email.dateStr;
      lines.push(`### ${currentDate}`);
    }
    lines.push(`- **Subject:** ${email.subject}`);
    lines.push(`  - Direction: ${email.direction}`);
    if (email.threadId) {
      lines.push(`  - Thread: ${email.threadId}`);
    }
    if (email.messageId) {
      lines.push(`  - Message-ID: ${email.messageId}`);
    }
    lines.push("");
  }

  return lines.join("\n");
}

// ─── Main ───────────────────────────────────────────────────────────────────

async function main() {
  // Load clients from CSV
  console.error("Loading clients from CSV...");
  const clients = loadClients();
  console.error(`Loaded ${clients.size} client emails`);

  // Find mbox files
  const entries = fs.readdirSync(MBOX_DIR);
  const mboxFiles = entries
    .filter((e) => e.endsWith(".mbox"))
    .map((e) => path.join(MBOX_DIR, e));

  if (mboxFiles.length === 0) {
    console.error("No .mbox files found in", MBOX_DIR);
    process.exit(1);
  }

  console.error(`Found ${mboxFiles.length} mbox file(s)`);

  // Process each mbox file
  for (const file of mboxFiles) {
    console.error(`\nProcessing: ${path.basename(file)}`);
    await processMbox(file, clients);
  }

  // Ensure client directory exists
  if (!fs.existsSync(CLIENT_DIR)) {
    fs.mkdirSync(CLIENT_DIR, { recursive: true });
  }

  // Generate markdown files
  const usedFilenames = new Set<string>();
  let filesWritten = 0;
  let totalEmails = 0;

  for (const [, client] of clients) {
    // Resolve name for filename
    let name = client.parsedName;
    if (!name.firstName && !name.lastName && client.headerName) {
      name = parseName(decodeRFC2047(client.headerName));
    }

    const filename = makeFilename(name, client.email, usedFilenames);
    const markdown = generateMarkdown(client);
    const filePath = path.join(CLIENT_DIR, filename);

    fs.writeFileSync(filePath, markdown, "utf-8");
    filesWritten++;
    totalEmails += client.emails.length;
  }

  console.error(`\n=== Results ===`);
  console.error(`Client files written: ${filesWritten}`);
  console.error(`Total email records: ${totalEmails}`);
  console.error(`Output directory: ${CLIENT_DIR}`);
}

main().catch((err) => {
  console.error("Error:", err);
  process.exit(1);
});

